def dedupe(items):
    """The items without repeats, in order of first appearance."""
    return list(set(items))

files.stack.py:
class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        return self._items.pop()

    def __len__(self):
        return len(self._items)

